#define R iResolution.xy
#define T iTime
#define rot(n) mat2(cos(n),-sin(n),sin(n),cos(n))

float scene(vec3 p){
    p.xy *= rot(acos(-1.0)/4.0);
    vec2 i = floor(p.xy);
    vec3 q = vec3(fract(p.xy)*2.-1.,p.z);
    q.yz *= rot(.2);
    q.xy *= 4.;
    q.xy *= rot(-T+i.x);
    q.yz *= rot(T+i.y);
    return length(vec2(length(q.xy)-2.,q.z));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 2.*(fragCoord-R*.5)/R.y;
    uv.y = uv.y+T*.25;
    vec3 ro = vec3(uv,-2.);
    vec3 rd = vec3(0,0,1);

    vec3 po = ro;
    vec3 col = vec3(1.,.9,.85);

    vec3 acc;
    float t,h;
    for(int i=0; i<99; i++){
        vec3 q = po;
        h = scene(q)-.65;
        t += max(.02,h);
        po = ro+rd*t;
        acc += vec3(9.,5.,1.)*exp(-h*64.);
        if (t>1e3){
            break;
        }
    }
    acc = smoothstep(0.,1.,acc);

    col = col-acc;
    fragColor = vec4(pow(col,vec3(.454545)),1.0);
}
